const raw = $json;

// ============================================================
// 1. Resolve input
// ============================================================

// Hỗ trợ cả:
// 1. Input trực tiếp từ Build Production State
// 2. Input sau Read JSON → Extract from File
const data = raw.data || raw;

// Canonical production state
const state = data.production_state || data;

if (!state || typeof state !== 'object') {
  throw new Error('Production state is missing or invalid.');
}

// ============================================================
// 2. Resolve callback
// ============================================================

let callback = null;

try {
  callback = $('Parse Callback').first().json;
} catch (_) {
  callback = null;
}

const run_id = String(
  state.run_id ||
  data.run_id ||
  callback?.run_id ||
  ''
).trim();

if (!run_id) {
  throw new Error('Missing run_id');
}

// ============================================================
// 3. Callback / routing
// ============================================================

const isCallback = Boolean(
  callback?.callback_action ||
  callback?.callback_target ||
  callback?.callback_id ||
  callback?.callback_data
);

const callback_action =
  callback?.callback_action || null;

const callback_target =
  callback?.callback_target || null;

const mode =
  !isCallback
    ? 'initial'
    : callback_action === 'regenerate'
      ? 'regenerate'
      : callback_action === 'generate_video'
        ? 'generate_video'
        : callback_action === 'add_music'
          ? 'add_music'
          : callback_action === 'upload'
            ? 'upload_youtube'
            : callback_action === 'suno_data'
              ? 'suno_data'
              : callback?.mode ||
                callback?.route ||
                'initial';

// ============================================================
// 4. Current lyrics
// ============================================================

const lyricsCurrent =
  state.lyrics?.current || null;

const lyricsTitle =
  String(lyricsCurrent?.title || '').trim();

const lyricsText =
  String(lyricsCurrent?.lyrics || '').trim();

const sunoStyle =
  String(lyricsCurrent?.suno_style || '').trim();

const lyricsVersion =
  Number(
    state.lyrics?.current_version ||
    lyricsCurrent?.version ||
    0
  );

// ============================================================
// 5. Current image
// ============================================================

const image =
  state.image?.current || null;

const imagePath =
  String(image?.path || '').trim();

const imagePrompt =
  String(image?.prompt || '').trim();

const imageVersion =
  Number(
    image?.version ||
    state.image?.current_version ||
    0
  );

// ============================================================
// 6. Video
// ============================================================

const video =
  state.video || {};

const videoPath =
  String(video.path || '').trim();

const videoFilename =
  String(video.filename || '').trim();

const videoPrompt =
  String(video.prompt || '').trim();

const videoDuration =
  Number(video.duration_seconds ?? 5);

// ============================================================
// 7. Audio
// ============================================================

const audio =
  state.audio || {};

const audioPath =
  String(audio.path || '').trim();

const audioFilename =
  String(audio.filename || '').trim();

// ============================================================
// 8. Final video
// ============================================================

const finalVideo =
  state.final_video || {};

const finalVideoPath =
  String(finalVideo.path || '').trim();

const finalVideoFilename =
  String(finalVideo.filename || '').trim();

// ============================================================
// 9. YouTube metadata
// ============================================================

const youtubeMeta =
  state.youtube_meta || {};

const youtubeMetaVersion =
  Number(youtubeMeta.version || 0);

// ============================================================
// 10. Return normalized runtime input
// ============================================================

return [
  {
    json: {
      // ========================================================
      // IDENTIFIERS
      // ========================================================

      run_id,

      chat_id:
        state.chat_id ??
        callback?.chat_id ??
        '',

      message_id:
        state.message_id ??
        callback?.message_id ??
        '',

      user_id:
        state.user_id ??
        null,

      username:
        state.username ??
        null,

      // ========================================================
      // CALLBACK
      // ========================================================

      callback_id:
        callback?.callback_id ??
        null,

      callback_data:
        callback?.callback_data ??
        null,

      callback_action,

      callback_target,

      // ========================================================
      // ROUTING
      // ========================================================

      mode,

      route:
        callback?.route ??
        null,

      // ========================================================
      // PRODUCTION INPUT
      // ========================================================

      intent:
        state.intent ??
        null,

      source_type:
        state.source_type ??
        '',

      source_text:
        state.source_text ??
        '',

      concept:
        state.concept ??
        '',

      language:
        state.language ??
        'Vietnamese',

      lyrics_style:
        state.lyrics_style ??
        '',

      visual_direction:
        state.visual_direction ??
        '',

      requested_action:
        state.requested_action ??
        null,

      // ========================================================
      // LYRICS
      // ========================================================

      title:
        lyricsTitle,

      lyrics:
        lyricsText,

      suno_style:
        sunoStyle,

      lyrics_version:
        lyricsVersion,

      lyrics_current:
        lyricsCurrent,

      lyrics_path:
        String(lyricsCurrent?.path || '').trim(),

      lyrics_word_count:
        Number(lyricsCurrent?.word_count || 0),

      // ========================================================
      // IMAGE
      // ========================================================

      image_prompt:
        imagePrompt,

      image_path:
        imagePath,

      image_version:
        imageVersion,

      image_current:
        image,

      image_filename:
        String(image?.filename || '').trim(),

      image_subfolder:
        String(image?.subfolder || '').trim(),

      image_type:
        String(image?.type || '').trim(),

      image_seed:
        image?.seed ?? null,

      // ========================================================
      // VIDEO
      // ========================================================

      video_path:
        videoPath,

      video_filename:
        videoFilename,

      video_prompt:
        videoPrompt,

      video_duration:
        videoDuration,

      // ========================================================
      // AUDIO
      // ========================================================

      audio_path:
        audioPath,

      audio_filename:
        audioFilename,

      // ========================================================
      // FINAL VIDEO
      // ========================================================

      final_video_path:
        finalVideoPath,

      final_video_filename:
        finalVideoFilename,

      // ========================================================
      // YOUTUBE META
      // ========================================================

      youtube_meta:
        youtubeMeta,

      youtube_title:
        String(youtubeMeta.title || '').trim(),

      youtube_description:
        String(youtubeMeta.description || '').trim(),

      youtube_tags:
        Array.isArray(youtubeMeta.tags)
          ? youtubeMeta.tags
          : [],

      youtube_hashtags:
        Array.isArray(youtubeMeta.hashtags)
          ? youtubeMeta.hashtags
          : [],

      youtube_category_id:
        String(youtubeMeta.category_id || '10'),

      youtube_privacy_status:
        String(youtubeMeta.privacy_status || 'private'),

      youtube_meta_version:
        youtubeMetaVersion,

      // ========================================================
      // YOUTUBE UPLOAD
      // ========================================================

      youtube_upload:
        state.youtube_upload || null,

      youtube_video_id:
        state.youtube_upload?.video_id ||
        null,

      youtube_url:
        state.youtube_upload?.url ||
        null,

      // ========================================================
      // STATUS
      // ========================================================

      status:
        state.status || {},

      // ========================================================
      // FULL CANONICAL STATE
      // ========================================================

      production_state:
        state
    }
  }
];

const upload = $json;

// ============================================================
// 1. Get source context from Prepare Upload YouTube
// ============================================================

const source = $('Prepare Upload YouTube').first().json;

const run_id = String(
  source.run_id ||
  ''
);

const chat_id = source.chat_id;

if (!run_id) {
  throw new Error('Missing run_id while saving YouTube upload');
}

// ============================================================
// 2. Get production state from current workflow data
// ============================================================

const state = source.production_state;

if (!state) {
  throw new Error(
    `Production state not found while saving YouTube upload: ${run_id}`
  );
}

// ============================================================
// 3. Extract YouTube upload result
// ============================================================

const videoId =
  upload.id ||
  upload.videoId ||
  upload.video_id ||
  null;

const url =
  upload.url ||
  (
    videoId
      ? `https://www.youtube.com/watch?v=${videoId}`
      : null
  );

if (!videoId) {
  throw new Error(
    `YouTube upload succeeded without a video ID: ${run_id}`
  );
}

const uploadedAt = new Date().toISOString();

// ============================================================
// 4. Update production state
// ============================================================

state.youtube_upload = {
  status: 'uploaded',
  video_id: videoId,
  url,
  uploaded_at: uploadedAt,
  metadata_version: Number(
    state.youtube_meta?.version || 0
  )
};

state.status = state.status || {};
state.status.youtube_upload = 'ready';

state.updated_at = uploadedAt;

// ============================================================
// 5. Return updated production state
//    → Convert to File
//    → Write JSON
// ============================================================

return [
  {
    json: {
      ...source,

      run_id,
      chat_id,

      production_state: state,

      youtube_upload: state.youtube_upload,

      state_saved: false
    }
  }
];

